rte_cards, rte_chaps=[],[]
for n,(num,topic,summ,prov,tags) in enumerate(rte):
    if str(num).startswith("अनुसूची"):
        label, fname, ct = "अनुसूची", "schedule", "note"
    else:
        label, fname, ct = f"धारा {num}", f"sec_{num}", "rule"
    rte_cards.append(card(f"rte_{fname}",RTE,RTE_DEPT,label,f"{label} — {topic}",summ,prov,tags,label,ctype=ct))
    rte_chaps.append(chap(n,num,topic,fname,f"# {label} — {topic}\n\n"+"\n\n".join(prov),RTE))

def dump(name,data):
    p=os.path.join(ROOT,name); json.dump(data,open(p,"w",encoding="utf-8"),ensure_ascii=False,indent=2)
    print(f"wrote {name}: {len(data)} items")
dump("bea_index.json",bea_chaps); dump("rte_index.json",rte_chaps)
kbp=os.path.join(ROOT,"knowledge.json"); kb=json.load(open(kbp)); before=len(kb)
kb.extend(bea_cards); kb.extend(rte_cards)
json.dump(kb,open(kbp,"w",encoding="utf-8"),ensure_ascii=False,indent=2)
print(f"knowledge.json: {before} -> {len(kb)} (+{len(bea_cards)} BEA, +{len(rte_cards)} RTE)")
